// @vitest-environment jsdom

import { cleanup, render, screen } from "@testing-library/react"
import { afterEach, describe, expect, it, vi } from "vitest"
import { QueryClient, QueryClientProvider } from "@tanstack/react-query"
import Root from "./App"

vi.mock("./components/features/ScrollToTop", () => ({
    ScrollToTop: () => null,
}))

afterEach(cleanup)

describe("application routes", () => {
    it("shows a useful not-found page for unknown URLs", () => {
        window.history.pushState({}, "", "/does-not-exist")
        const queryClient = new QueryClient()

        render(
            <QueryClientProvider client={queryClient}>
                <Root />
            </QueryClientProvider>,
        )

        expect(screen.getByRole("heading", { name: "This page isn’t here." })).toBeTruthy()
        expect(screen.getByRole("link", { name: "Back to explore" }).getAttribute("href")).toBe("/")
        queryClient.clear()
    })
})

const AuthCallback = () => {
    const navigate = useNavigate()
    const [error, setError] = useState("")

    useEffect(() => {
        let isMounted = true
        const completeSignIn = async () => {
            if (!supabase) {
                setError("Sign-in is unavailable because Supabase is not configured.")
                return
            }

            const callbackUrl = new URL(window.location.href)
            const providerError = callbackUrl.searchParams.get("error_description")
                ?? callbackUrl.searchParams.get("error")
            if (providerError) {
                window.history.replaceState({}, document.title, callbackUrl.pathname)
                setError(providerError)
                return
            }

            const { data, error: sessionError } = await supabase.auth.getSession()
            if (!isMounted) return

            if (sessionError) {
                setError(sessionError.message)
                return
            }
            if (!data.session) {
                setError("Google sign-in did not return a session. Please try again.")
                return
            }

            window.history.replaceState({}, document.title, callbackUrl.pathname)
            navigate(getSafeReturnPath(), { replace: true })
        }

        void completeSignIn().catch(callbackError => {
            if (isMounted) {
                setError(callbackError instanceof Error ? callbackError.message : "Unable to complete sign-in.")
            }
        })

        return () => {
            isMounted = false
        }
    }, [navigate])

    return (
        <section className="grid min-h-dvh w-full place-items-center overflow-y-auto bg-[#fdfcfb] px-5 py-10 text-neutral-800 dark:bg-[#121110] dark:text-neutral-100">
            <div className="max-w-md text-center">
                {error
                    ? (
                        <>
                            <h1 className="text-2xl font-medium text-neutral-900 dark:text-neutral-100">Sign-in couldn’t be completed</h1>
                            <p role="alert" className="mt-3 break-words text-sm leading-6 text-neutral-500 dark:text-neutral-400">{error}</p>
                            <Link
                                to="/"
                                className="mt-5 inline-flex min-h-11 items-center gap-2 rounded-xl border border-black/10 bg-white px-4 text-sm font-medium text-neutral-700 transition hover:bg-black/[0.03] dark:border-white/10 dark:bg-[#1a1917] dark:text-neutral-200 dark:hover:bg-white/[0.05]"
                            >
                                <RotateCw size={16} aria-hidden="true" /> Return to Lucea
                            </Link>
                        </>
                    )
                    : (
                        <>
                            <LoaderCircle size={25} className="mx-auto animate-spin text-neutral-500 dark:text-neutral-400" aria-hidden="true" />
                            <h1 className="mt-4 text-xl font-medium text-neutral-900 dark:text-neutral-100">Finishing sign-in</h1>
                            <p className="mt-2 text-sm text-neutral-500 dark:text-neutral-400">You’ll be redirected in a moment.</p>
                        </>
                    )
                }
            </div>
        </section>
    )
}

const AuthProvider = ({ children }: { children: ReactNode }) => {
    const [session, setSession] = useState<Session | null>(null)
    const [isAuthLoading, setIsAuthLoading] = useState(true)
    const [isAuthDialogOpen, setIsAuthDialogOpen] = useState(false)
    const [authPrompt, setAuthPrompt] = useState<string | null>(null)

    useEffect(() => {
        if (!supabase) {
            setIsAuthLoading(false)
            return
        }

        let isMounted = true
        const applySession = (nextSession: Session | null) => {
            if (!isMounted) return
            setSession(nextSession)
            if (nextSession?.user && nextSession.access_token) {
                void useMoodboards.getState().syncWithAccount(
                    nextSession.user.id,
                    nextSession.access_token,
                )
            } else {
                useMoodboards.getState().clearAccount()
            }
        }

        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, nextSession) => {
            applySession(nextSession)
            setIsAuthLoading(false)
        })

        void supabase.auth.getSession().then(({ data, error }) => {
            if (error) console.error("Unable to restore the Supabase session:", error)
            applySession(data.session)
            setIsAuthLoading(false)
        })

        return () => {
            isMounted = false
            subscription.unsubscribe()
        }
    }, [])

    const value = useMemo<AuthContextValue>(() => ({
        user: session?.user ?? null,
        accessToken: session?.access_token ?? null,
        isAuthConfigured: supabase !== null,
        isAuthLoading,
        isAuthDialogOpen,
        authPrompt,
        openAuthDialog: (prompt?: string) => {
            setAuthPrompt(prompt ?? null)
            setIsAuthDialogOpen(true)
        },
        closeAuthDialog: () => {
            setAuthPrompt(null)
            setIsAuthDialogOpen(false)
        },
        supabase,
    }), [session, isAuthLoading, isAuthDialogOpen, authPrompt])

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

const HorizontalScroller = ({ children, label }: HorizontalScrollerProps) => {
    const scrollRef = useRef<HTMLDivElement>(null)
    const [canScrollLeft, setCanScrollLeft] = useState(false)
    const [canScrollRight, setCanScrollRight] = useState(false)

    useEffect(() => {
        const element = scrollRef.current
        if (!element) return

        const updateScrollButtons = () => {
            setCanScrollLeft(element.scrollLeft > 0)
            setCanScrollRight(element.scrollLeft + element.clientWidth < element.scrollWidth - 1)
        }

        updateScrollButtons()
        element.addEventListener("scroll", updateScrollButtons, { passive: true })
        const resizeObserver = new ResizeObserver(updateScrollButtons)
        resizeObserver.observe(element)
        if (element.firstElementChild) resizeObserver.observe(element.firstElementChild)

        return () => {
            element.removeEventListener("scroll", updateScrollButtons)
            resizeObserver.disconnect()
        }
    }, [children])

    const scroll = (direction: -1 | 1) => {
        const element = scrollRef.current
        if (!element) return
        element.scrollBy({
            left: direction * Math.max(element.clientWidth * 0.75, 160),
            behavior: "smooth",
        })
    }

    return (
        <div role="group" aria-label={label} className="relative min-w-0">
            <div
                ref={scrollRef}
                className="scrollbar-hide w-full overflow-x-auto overscroll-x-contain"
            >
                {children}
            </div>
            <div
                aria-hidden="true"
                className={`pointer-events-none absolute inset-y-0 left-0 z-[5] w-10 bg-gradient-to-r from-[#fdfcfb] via-[#fdfcfb]/90 to-transparent dark:from-[#121110] dark:via-[#121110]/90 transition-opacity duration-300 ${
                    canScrollLeft ? "opacity-100" : "opacity-0"
                }`}
            />
            <div
                aria-hidden="true"
                className={`pointer-events-none absolute inset-y-0 right-0 z-[5] w-10 bg-gradient-to-l from-[#fdfcfb] via-[#fdfcfb]/90 to-transparent dark:from-[#121110] dark:via-[#121110]/90 transition-opacity duration-300 ${
                    canScrollRight ? "opacity-100" : "opacity-0"
                }`}
            />
            <button
                type="button"
                aria-label={`Scroll ${label} left`}
                tabIndex={canScrollLeft ? 0 : -1}
                onClick={() => scroll(-1)}
                className={`absolute left-1 top-1/2 z-10 grid size-8 -translate-y-1/2 place-items-center rounded-full text-neutral-700 transition-all duration-300 hover:bg-white/80 hover:text-neutral-950 hover:shadow-sm focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-700 dark:text-neutral-300 dark:hover:bg-[#282522] dark:hover:text-white ${
                    canScrollLeft
                        ? "translate-x-0 opacity-100"
                        : "pointer-events-none -translate-x-1 opacity-0"
                }`}
            >
                <ChevronLeft size={18} aria-hidden="true" />
            </button>
            <button
                type="button"
                aria-label={`Scroll ${label} right`}
                tabIndex={canScrollRight ? 0 : -1}
                onClick={() => scroll(1)}
                className={`absolute right-1 top-1/2 z-10 grid size-8 -translate-y-1/2 place-items-center rounded-full text-neutral-700 transition-all duration-300 hover:bg-white/80 hover:text-neutral-950 hover:shadow-sm focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-700 dark:text-neutral-300 dark:hover:bg-[#282522] dark:hover:text-white ${
                    canScrollRight
                        ? "translate-x-0 opacity-100"
                        : "pointer-events-none translate-x-1 opacity-0"
                }`}
            >
                <ChevronRight size={18} aria-hidden="true" />
            </button>
        </div>
    )
}

