const PublicMoodboardCard = ({
    moodboard,
    showCreator = true,
}: {
    moodboard: PublicMoodboardSummary
    showCreator?: boolean
}) => {
    const preview = moodboard.preview.slice(0, 3)

    return (
        <article className="group relative overflow-hidden rounded-[20px] bg-neutral-200 transition-shadow duration-300 hover:shadow-lg dark:bg-neutral-800 dark:hover:shadow-[0_12px_28px_rgba(0,0,0,0.5)]">
            <Link
                to={`/profiles/${encodeURIComponent(moodboard.handle)}/boards/${encodeURIComponent(moodboard.id)}`}
                aria-label={`${moodboard.title}, ${moodboard.mediaCount} saved ${moodboard.mediaCount === 1 ? "item" : "items"}`}
                className="relative block aspect-[4/3] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-800"
            >
                <div className={`absolute inset-0 overflow-hidden ${preview.length > 1 ? "grid grid-cols-3 grid-rows-2 gap-1 bg-[#fdfcfb] dark:bg-[#121110]" : "bg-gradient-to-br from-neutral-100 to-[#f4efe9] dark:from-neutral-900 dark:to-[#1a1917]"}`}>
                    {preview.length === 0 ? (
                        <span className="grid h-full place-items-center text-neutral-500 dark:text-neutral-400">
                            <span className="flex items-center gap-2 text-sm"><ImagePlus size={17} aria-hidden="true" /> No saved items yet</span>
                        </span>
                    ) : (
                        preview.map((item, index) => (
                            <div
                                key={item.key}
                                className={`relative min-h-0 min-w-0 overflow-hidden ${
                                    preview.length === 1
                                        ? "h-full w-full"
                                        : index === 0
                                            ? "col-span-2 row-span-2"
                                            : preview.length === 2
                                                ? "col-span-1 row-span-2"
                                                : "col-span-1 row-span-1"
                                }`}
                            >
                                <img
                                    src={item.thumbnail}
                                    alt=""
                                    loading="lazy"
                                    className="h-full w-full object-cover motion-safe:transition-transform motion-safe:duration-500 motion-safe:ease-out motion-safe:group-hover:scale-[1.04]"
                                />
                                {index === preview.length - 1 && moodboard.mediaCount > preview.length && (
                                    <span className="absolute inset-0 grid place-items-center bg-black/40 text-lg font-medium text-white">
                                        +{moodboard.mediaCount - preview.length}
                                    </span>
                                )}
                            </div>
                        ))
                    )}
                </div>
                <span aria-hidden="true" className="absolute inset-x-0 bottom-0 h-36 bg-gradient-to-t from-black/80 via-black/25 to-transparent" />
                <span className="absolute inset-x-0 bottom-0 flex items-end justify-between gap-2 px-3 pb-3 sm:gap-3 sm:px-5 sm:pb-5">
                    <span className="min-w-0">
                        <span className="block truncate font-editorial text-base font-normal text-white sm:text-2xl">{moodboard.title}</span>
                        <span className="mt-0.5 block text-[11px] text-white/85 sm:text-xs">
                            {moodboard.mediaCount} {moodboard.mediaCount === 1 ? "item" : "items"}
                        </span>
                    </span>
                    <ArrowUpRight size={16} className="mb-1 shrink-0 text-white/85 transition-transform duration-200 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 sm:size-[19px]" aria-hidden="true" />
                </span>
            </Link>
            {showCreator && (
                <div className="border-t border-black/[0.06] bg-[#fdfcfb] px-4 py-2.5 text-xs text-neutral-500 dark:border-white/[0.06] dark:bg-[#1a1917] dark:text-neutral-400 sm:px-5">
                    by{" "}
                    <Link
                        to={`/profiles/${encodeURIComponent(moodboard.handle)}`}
                        className="font-medium text-neutral-700 transition hover:text-neutral-950 hover:underline hover:underline-offset-2 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-700 dark:text-neutral-200 dark:hover:text-white"
                    >
                        {moodboard.handle}
                    </Link>
                </div>
            )}
        </article>
    )
}

const QueryFeedback = ({
    error,
    empty = false,
    onRetry,
    isRetrying = false,
    className,
}: QueryFeedbackProps) => {
    const hasError = Boolean(error)
    if (!hasError && !empty) return null
    const isRateLimited = typeof error === "object"
        && error !== null
        && "response" in error
        && typeof error.response === "object"
        && error.response !== null
        && "status" in error.response
        && error.response.status === 429

    const message = hasError
        ? isRateLimited
            ? "We're taking a short breather. Give it a moment, then try again."
            : "We couldn't bring these visuals in. Please try again."
        : "No visuals found for this search."

    if (hasError && isRetrying) {
        return (
            <div
                role="status"
                className={`mx-auto ${className ?? "my-6"} flex w-full max-w-xl items-center justify-center gap-2.5 rounded-2xl border border-black/[0.06] bg-white/70 px-4 py-4 text-sm text-neutral-500 dark:border-white/[0.08] dark:bg-[#1a1917]/70 dark:text-neutral-400`}
            >
                <LoaderCircle size={16} className="animate-spin text-neutral-600 dark:text-neutral-300" aria-hidden="true" />
                <span>Taking another look…</span>
            </div>
        )
    }

    return (
        <div
            role={hasError ? "alert" : "status"}
            className={`mx-auto ${className ?? "my-8"} flex w-full max-w-xl flex-col items-center rounded-3xl border border-black/[0.07] bg-white/80 px-5 py-8 text-center shadow-[0_8px_32px_rgba(35,29,22,0.035)] sm:px-8 sm:py-10 dark:border-white/[0.08] dark:bg-[#1a1917]/90`}
        >
            <span className={`grid size-12 place-items-center rounded-2xl ${hasError ? "bg-[#f5eee7] text-neutral-700 dark:bg-[#28221c] dark:text-neutral-200" : "bg-neutral-100 text-neutral-500 dark:bg-[#25221e] dark:text-neutral-400"}`}>
                {hasError
                    ? <AlertCircle size={21} strokeWidth={1.7} aria-hidden="true" />
                    : <ImageOff size={21} strokeWidth={1.7} aria-hidden="true" />
                }
            </span>
            <h2 className="mt-4 text-base font-semibold text-neutral-800 dark:text-neutral-100">
                {hasError ? "We hit a small snag" : "A quiet corner"}
            </h2>
            <p className="mt-1.5 max-w-sm text-sm leading-6 text-neutral-500 dark:text-neutral-400">{message}</p>
            {empty && (
                <div className="mt-6 flex flex-col items-center">
                    <p className="flex items-center gap-1.5 text-xs font-medium text-neutral-400 dark:text-neutral-500">
                        <Sparkles size={13} className="text-amber-600 dark:text-amber-400" aria-hidden="true" />
                        Explore trending ideas instead
                    </p>
                    <div className="mt-3 flex flex-wrap justify-center gap-2">
                        {suggestedSearches.map(tag => (
                            <Link
                                key={tag}
                                to={`/search?query=${encodeURIComponent(tag)}&type=photos`}
                                className="inline-flex min-h-8 items-center rounded-full border border-black/[0.08] bg-white px-3 text-xs font-medium text-neutral-700 shadow-xs transition hover:border-black/20 hover:bg-[#f6f2ec] hover:text-neutral-900 active:scale-95 dark:border-white/10 dark:bg-[#25221e] dark:text-neutral-200 dark:hover:bg-[#2e2a25] dark:hover:text-white"
                            >
                                {tag}
                            </Link>
                        ))}
                    </div>
                </div>
            )}
            {hasError && onRetry && (
                <div className="mt-5 flex flex-wrap items-center justify-center gap-2.5">
                    <button
                        type="button"
                        onClick={onRetry}
                        className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-neutral-900 px-4 text-sm font-medium text-white shadow-xs transition hover:bg-neutral-800 active:scale-[0.98] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-700 dark:bg-white dark:text-neutral-900 dark:hover:bg-neutral-200"
                    >
                        <RotateCw size={15} aria-hidden="true" />
                        Try again
                    </button>
                </div>
            )}
        </div>
    )
}

const SearchFilterDropdown = ({ label, value, options, onChange }: SearchFilterDropdownProps) => {
    const [isOpen, setIsOpen] = useState(false)
    const [activeIndex, setActiveIndex] = useState(0)
    const containerRef = useRef<HTMLDivElement>(null)
    const triggerRef = useRef<HTMLButtonElement>(null)
    const optionRefs = useRef<Array<HTMLButtonElement | null>>([])
    const selectedOption = options.find(option => option.value === value) ?? options[0]

    useEffect(() => {
        const closeOnOutsideClick = (event: PointerEvent) => {
            if (!containerRef.current?.contains(event.target as Node)) setIsOpen(false)
        }
        document.addEventListener("pointerdown", closeOnOutsideClick)
        return () => document.removeEventListener("pointerdown", closeOnOutsideClick)
    }, [])

    const chooseOption = (option: SearchFilterOption) => {
        onChange(option.value)
        setIsOpen(false)
        triggerRef.current?.focus()
    }

    const handleMenuKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        if (event.key === "Escape") {
            event.preventDefault()
            setIsOpen(false)
            triggerRef.current?.focus()
            return
        }

        if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return
        event.preventDefault()
        const direction = event.key === "ArrowDown" ? 1 : -1
        const nextIndex = (activeIndex + direction + options.length) % options.length
        setActiveIndex(nextIndex)
        optionRefs.current[nextIndex]?.focus()
    }

    return (
        <div ref={containerRef} className="relative min-w-0">
            <button
                ref={triggerRef}
                type="button"
                aria-haspopup="listbox"
                aria-expanded={isOpen}
                onClick={() => {
                    if (!isOpen) setActiveIndex(options.findIndex(option => option.value === value))
                    setIsOpen(open => !open)
                }}
                onKeyDown={event => {
                    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
                        event.preventDefault()
                        setIsOpen(true)
                        const selectedIndex = options.findIndex(option => option.value === value)
                        const direction = event.key === "ArrowDown" ? 1 : -1
                        const nextIndex = (selectedIndex + direction + options.length) % options.length
                        setActiveIndex(nextIndex)
                        window.setTimeout(() => optionRefs.current[nextIndex]?.focus(), 0)
                    }
                }}
                className={`group flex min-h-8 w-full items-center gap-1.5 border-b px-1 text-left transition focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-700 sm:min-h-9 sm:gap-2 ${
                    isOpen ? "border-neutral-700 dark:border-neutral-300" : "border-transparent hover:border-black/20 dark:hover:border-white/20"
                }`}
            >
                <span className="text-[10px] text-neutral-400 dark:text-neutral-500 sm:text-[11px]">{label}</span>
                <span className="min-w-0 truncate text-xs font-medium text-neutral-800 dark:text-neutral-200 sm:text-[13px]">
                    {selectedOption.label}
                </span>
                <ChevronDown
                    size={12}
                    className={`shrink-0 text-neutral-400 dark:text-neutral-500 transition-transform duration-200 ${isOpen ? "rotate-180" : ""}`}
                    aria-hidden="true"
                />
            </button>

            {isOpen && (
                <div
                    role="listbox"
                    aria-label={label}
                    onKeyDown={handleMenuKeyDown}
                    onBlur={event => {
                        if (!event.relatedTarget || !containerRef.current?.contains(event.relatedTarget as Node)) {
                            setIsOpen(false)
                        }
                    }}
                    className="absolute right-0 top-[calc(100%+8px)] z-40 w-[min(17rem,calc(100vw-2rem))] overflow-hidden rounded-2xl border border-black/[0.08] bg-white p-1.5 shadow-[0_14px_38px_rgba(35,29,22,0.12)] dark:border-white/10 dark:bg-[#1a1917]"
                >
                    {options.map((option, index) => {
                        const OptionIcon = option.icon
                        const isSelected = option.value === value
                        return (
                            <button
                                key={option.value}
                                ref={element => { optionRefs.current[index] = element }}
                                type="button"
                                role="option"
                                aria-selected={isSelected}
                                onFocus={() => setActiveIndex(index)}
                                onClick={() => chooseOption(option)}
                                className={`flex min-h-12 w-full items-center gap-2.5 rounded-xl px-2 text-left transition focus-visible:outline-2 focus-visible:outline-inset focus-visible:outline-neutral-500 sm:min-h-[54px] sm:gap-3 sm:px-2.5 ${
                                    isSelected ? "bg-[#f6f3ee] dark:bg-[#282420]" : "hover:bg-[#faf8f5] dark:hover:bg-[#221f1c]"
                                }`}
                            >
                                <span className={`grid size-7 shrink-0 place-items-center rounded-lg sm:size-8 ${
                                    isSelected ? "bg-white text-neutral-800 shadow-sm dark:bg-[#34302b] dark:text-neutral-100" : "bg-[#f7f5f1] text-neutral-500 dark:bg-[#25221e] dark:text-neutral-400"
                                }`}>
                                    <OptionIcon size={13} className="sm:size-[15px]" strokeWidth={1.7} aria-hidden="true" />
                                </span>
                                <span className="min-w-0 flex-1">
                                    <span className={`block text-xs sm:text-sm ${isSelected ? "font-medium text-neutral-900 dark:text-white" : "text-neutral-700 dark:text-neutral-300"}`}>
                                        {option.label}
                                    </span>
                                    <span className="block truncate text-[11px] text-neutral-400 dark:text-neutral-500 sm:text-xs">{option.description}</span>
                                </span>
                                {isSelected && <Check size={14} className="shrink-0 text-neutral-700 dark:text-neutral-300 sm:size-[15px]" aria-hidden="true" />}
                            </button>
                        )
                    })}
                </div>
            )}
        </div>
    )
}

