import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import './styles/index.css'
import App from './App.tsx'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import axios from 'axios'
import { applyTheme, getStoredTheme } from './hooks/useTheme'

// Initialize theme on initial load
applyTheme(getStoredTheme())

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: (failureCount, error) => {
        if (
          axios.isAxiosError(error)
          && error.response
          && error.response.status >= 400
          && error.response.status < 500
        ) {
          return false
        }
        return failureCount < 1
      },
    },
  },
})

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <QueryClientProvider client={queryClient} >
      <App />
    </QueryClientProvider>
  </StrictMode>,
)

// @vitest-environment jsdom

import { cleanup, render, screen } from "@testing-library/react"
import { afterEach, describe, expect, it, vi } from "vitest"
import { MemoryRouter } from "react-router-dom"
import Home from "./Home"

vi.mock("./Media", () => ({ default: () => <div /> }))
vi.mock("./Suggestions", () => ({ default: () => <div /> }))
vi.mock("./Featured", () => ({ default: () => <div /> }))
vi.mock("./Topic", () => ({ Topic: () => <div /> }))
vi.mock("@/hooks/useDailyTopics", () => ({
    default: () => ({ topicsReady: true }),
}))

afterEach(() => {
    cleanup()
    vi.restoreAllMocks()
})

describe("Home", () => {
    it("renders without updating shared state during render", () => {
        const consoleError = vi.spyOn(console, "error").mockImplementation(() => {})

        render(
            <MemoryRouter initialEntries={["/"]}>
                <Home />
            </MemoryRouter>,
        )

        expect(screen.getByRole("heading", { name: "Still & Moving" })).toBeTruthy()
        expect(
            consoleError.mock.calls.flat().join(" "),
        ).not.toContain("Cannot update a component")

    })
})

const Media = ({ filter }: MediaProps) => {
    const {
        data,
        fetchNextPage,
        isFetchingNextPage,
        isFetching,
        isPending,
        isError,
        error,
        refetch,
    } = useInfiniteQuery({
        queryKey: ["home", "media"],
        queryFn: async ({ pageParam, signal }) => {
            const [photos, videos] = await Promise.all([
                fetchCuratedPhotos(pageParam, 8, signal),
                fetchPopularVideos(pageParam, 6, signal),
            ])
            return {
                data: [...photos.data, ...videos.data],
                nextPage: photos.nextPage ?? videos.nextPage,
            }
        },
        getNextPageParam: (lastPage) => lastPage.nextPage,
        initialPageParam: 1,
    });

    const allMedia = data?.pages.flatMap(pg => pg.data) ?? []
    const mediaList = filter === "all"
        ? allMedia
        : allMedia.filter(media => filter === "photos" ? "src" in media : "video_files" in media)
    const columnsCountBreakPoints = filter === "videos" ? VIDEO_MASONRY_COLUMNS : MASONRY_COLUMNS

    if (isPending && !isError) {
        return (
            <ResponsiveMasonry columnsCountBreakPoints={columnsCountBreakPoints}>
                <Masonry gutter={MASONRY_GUTTER} sequential>
                    {Array.from({ length: 12 }).map((_, index) =>
                        index % 2 === 0
                            ? <EvenSkeletonCard key={index} />
                            : <OddSkeletonCard key={index} />
                    )}
                </Masonry>
            </ResponsiveMasonry>
        )
    }

    if (mediaList.length === 0) {
        return <QueryFeedback error={error} empty={!isError} isRetrying={isFetching} onRetry={() => void refetch()} />
    }

    return (
        <>
        <InfiniteScroll
            dataLength={mediaList.length}
            hasMore={!!data?.pages.at(-1)?.nextPage}
            next={fetchNextPage}
            loader={<div></div>}
        >
            <ResponsiveMasonry columnsCountBreakPoints={columnsCountBreakPoints}>
                <Masonry gutter={MASONRY_GUTTER} sequential>
                    {mediaList.map((media) => {

                        if ("src" in media) {
                            if (!media?.src?.large) return null

                            return <ImageItem image={media} key={media.id} />
                        }

                        if (!("video_files" in media)) return null

                        return <VideoItem key={media.id} video={media} />
                    })}

                    {isFetchingNextPage
                        ? Array.from({ length: 8 }).map((_, i) => {
                            if (i % 2 == 0) return <EvenSkeletonCard key={i} />
                            return <OddSkeletonCard key={i} />
                        })
                        : null
                    }
                </Masonry>
            </ResponsiveMasonry>
        </InfiniteScroll>
        {isError && <QueryFeedback error={error} isRetrying={isFetching} onRetry={() => void refetch()} />}
        </>
    )
}

