// @vitest-environment jsdom

import { cleanup, render, screen } from "@testing-library/react"
import { afterEach, describe, expect, it, vi } from "vitest"
import type { ReactNode } from "react"
import { MemoryRouter, Route, Routes } from "react-router-dom"
import Suggestions from "./Suggestions"
import { DEFAULT_TOPICS, useTopic } from "@/store/useTopic"

vi.mock("@/hooks/useDailyTopics", () => ({
    default: () => ({ isError: false, topicsReady: true }),
}))
vi.mock("@/components/features/HorizontalScroller", () => ({
    default: ({ children }: { children: ReactNode }) => <>{children}</>,
}))

afterEach(() => {
    cleanup()
    useTopic.setState({ topics: [] })
})

describe("Suggestions", () => {
    it("highlights the topic selected by the current route", () => {
        useTopic.setState({ topics: DEFAULT_TOPICS })

        render(
            <MemoryRouter initialEntries={["/t/travel"]}>
                <Routes>
                    <Route path="/t/:topicSlug" element={<Suggestions />} />
                </Routes>
            </MemoryRouter>,
        )

        expect(screen.queryByText("Today’s picks")).toBeNull()
        expect(screen.getByRole("link", { name: "Travel" }).getAttribute("aria-current")).toBe("page")
        expect(screen.getByRole("link", { name: "Nature" }).getAttribute("aria-current")).toBeNull()
    })
})

const Suggestions = () => {
    const { isError, topicsReady } = useDailyTopics()
    const topics = useTopic(state => state.topics)
    const { topicSlug: activeTopic } = useParams()

    return (
        <div className="flex h-[46px] min-w-0 items-center gap-4">
            <div className="min-w-0 flex-1">
                {topicsReady ? (
                    <HorizontalScroller label="today's visual topics">
                        <ul aria-label="Today’s visual topics" className="flex h-[46px] w-full items-center gap-5 whitespace-nowrap pr-8">
                            <li className="relative shrink-0">
                                <Link
                                    to="/"
                                    aria-current={!activeTopic ? "page" : undefined}
                                    className={`relative inline-flex items-center py-1 text-[13px] leading-none transition-colors duration-200 after:absolute after:inset-x-0 after:-bottom-1 after:h-px after:origin-left after:bg-neutral-900 after:content-[''] motion-safe:after:transition-transform motion-safe:after:duration-200 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-700 dark:focus-visible:outline-neutral-300 dark:after:bg-white sm:text-sm ${
                                        !activeTopic
                                            ? "text-neutral-900 after:scale-x-100 font-medium dark:text-white"
                                            : "text-neutral-500 after:scale-x-0 hover:text-neutral-900 hover:after:scale-x-100 focus-visible:after:scale-x-100 dark:text-neutral-400 dark:hover:text-white"
                                    }`}
                                >
                                    All
                                </Link>
                                <span aria-hidden="true" className="pointer-events-none absolute -right-3 top-1/2 size-0.5 -translate-y-1/2 rounded-full bg-neutral-300 dark:bg-neutral-700" />
                            </li>
                            {topics.map((topic, index) => (
                                <li key={topic.slug} className="relative shrink-0">
                                    <Link
                                        to={`/t/${topic.slug}`}
                                        aria-current={activeTopic === topic.slug ? "page" : undefined}
                                        className={`relative inline-flex items-center py-1 text-[13px] leading-none transition-colors duration-200 after:absolute after:inset-x-0 after:-bottom-1 after:h-px after:origin-left after:bg-neutral-900 after:content-[''] motion-safe:after:transition-transform motion-safe:after:duration-200 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-700 dark:focus-visible:outline-neutral-300 dark:after:bg-white sm:text-sm ${
                                            activeTopic === topic.slug
                                                ? "text-neutral-900 after:scale-x-100 font-medium dark:text-white"
                                                : "text-neutral-500 after:scale-x-0 hover:text-neutral-900 hover:after:scale-x-100 focus-visible:after:scale-x-100 dark:text-neutral-400 dark:hover:text-white"
                                        }`}
                                    >
                                        {topic.title}
                                    </Link>
                                    {index < topics.length - 1 && (
                                        <span aria-hidden="true" className="pointer-events-none absolute -right-3 top-1/2 size-0.5 -translate-y-1/2 rounded-full bg-neutral-300 dark:bg-neutral-700" />
                                    )}
                                </li>
                            ))}
                        </ul>
                    </HorizontalScroller>
                ) : (
                    <div role="status" aria-label="Loading daily topics" className="flex h-[46px] items-center gap-2">
                        <span className="size-3 animate-spin rounded-full border-2 border-neutral-300 border-t-neutral-700 dark:border-neutral-700 dark:border-t-neutral-200" />
                        <span className="text-xs text-neutral-400 dark:text-neutral-500">Finding today’s sparks…</span>
                    </div>
                )}
            </div>
            {isError && (
                <span className="sr-only" role="status">
                    Daily topics are temporarily unavailable. Showing the saved topic set.
                </span>
            )}
        </div>
    )
}

const TopicResultsHeader = ({ title, mediaFilter, onFilterChange }: TopicResultsHeaderProps) => (
    <header className="relative isolate mb-6 overflow-hidden rounded-[20px] border border-black/[0.06] bg-gradient-to-br from-[#f8f5ee] via-white to-[#f5f0e6] p-5 sm:p-7 dark:border-white/[0.08] dark:from-[#1b1916] dark:via-[#151312] dark:to-[#191714] shadow-xs">
        {/* Subtle decorative glow orb */}
        <div aria-hidden="true" className="pointer-events-none absolute -right-16 -top-16 size-64 rounded-full bg-amber-500/10 blur-3xl dark:bg-amber-400/5" />

        <div className="relative z-10 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
            <div className="min-w-0 animate-subtle-reveal">
                <div className="mb-1.5 flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-[0.18em] text-neutral-400 dark:text-neutral-400">
                    <Sparkles size={13} className="text-amber-500" aria-hidden="true" />
                    <span>Today’s visual field</span>
                    <span className="mx-1 text-neutral-300 dark:text-neutral-600">/</span>
                    <span>Curated topic</span>
                </div>
                <h1
                    className="font-editorial break-words text-[28px] sm:text-[38px] font-normal leading-tight text-neutral-900 dark:text-white tracking-[-0.015em]"
                >
                    {title}
                </h1>
                <p className="mt-1 text-xs sm:text-sm text-neutral-500 dark:text-neutral-300 font-normal">
                    A fresh trail of photos and motion, chosen for today.
                </p>
            </div>

            <div role="group" aria-label="Filter topic results by media type" className="flex items-center gap-1 rounded-full border border-black/[0.08] bg-white/90 p-1 backdrop-blur-sm dark:border-white/[0.08] dark:bg-[#1a1917]/90">
                {mediaFilters.map(({ value, label, Icon }) => (
                    <button
                        key={value}
                        type="button"
                        aria-pressed={mediaFilter === value}
                        onClick={() => onFilterChange(value)}
                        className={`inline-flex min-h-9 items-center gap-1.5 rounded-full px-3 text-xs font-medium transition-all duration-200 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-700 ${
                            mediaFilter === value
                                ? 'bg-neutral-900 text-white shadow-xs dark:bg-white dark:text-neutral-900'
                                : 'text-neutral-500 hover:bg-black/[0.05] hover:text-neutral-900 dark:text-neutral-400 dark:hover:bg-white/[0.05] dark:hover:text-white'
                        }`}
                    >
                        <Icon size={15} strokeWidth={1.8} aria-hidden="true" />
                        {label}
                    </button>
                ))}
            </div>
        </div>
    </header>
)

