const Heatmap = () => {
  const userId = useAppStore((state) => state.user?.id)
  const isDark = useAppStore((state) => state.isDark)
  const { data: tasksDone = [], error } = useTaskActivity(userId)

  const today = new Date();
  const startDate = new Date(today);
  startDate.setMonth(today.getMonth() - 6);
  startDate.setDate(startDate.getDate() - startDate.getDay());

  const endDate = new Date(today);
  endDate.setDate(endDate.getDate() + (6 - endDate.getDay()));

  const fullData = [];
  const cursor = new Date(startDate);
  while (cursor <= endDate) {
    fullData.push({ date: cursor.toISOString().split("T")[0], count: 0, level: 0 });
    cursor.setDate(cursor.getDate() + 1);
  }

  const mergedData = fullData.map((entry) => {
    const taskData = tasksDone.find((t: HeatmapData) => t._id === entry.date);
    const count = taskData ? taskData.count : 0;
    return {
      date: entry.date,
      count,
      level:
        count >= 4 ? 4 :
          count >= 3 ? 3 :
            count >= 2 ? 2 :
              count >= 1 ? 1 : 0,
    };
  });

  const darkPalette = [
    "#ffffff08",
    "#a3b4ff26",
    "#8799ff59",
    "#5a69ff99",
    "#5a69ff"
  ]

  const lightPalette = [
    "#1E1E2A",
    "#3A2F4D",
    "#5A4E82",
    "#7A6CC4",
    "#9B84FF"
  ]

  const dark = isDark ? darkPalette : lightPalette

  return (
    <motion.div>
      <Card className={`${isDark ? "text-slate-400 border-white/10 bg-white/2" : "text-[#2d3748] bg-white"} backdrop-blur-md border rounded-2xl p-6 w-full shadow-lg`}>
        {error && <p role="alert" className="pb-2 text-center text-sm text-red-400">Unable to load activity: {error.message}</p>}
        <div className="px-6 pt-2">
          <p className={`text-xs ${isDark ? "text-slate-500" : "text-black/40"} tracking-widest uppercase font-medium text-center`}>
            Weekly Activity
          </p>
          <p className={`text-sm ${isDark ? "text-white/80" : "text-[#2d3748]"} text-center`}>Last 6 months of productivity</p>
        </div>

        <CardContent className="p-0 overflow-x-auto max-w-full mx-auto h-full">
          <ActivityCalendar
            data={mergedData}
            hideTotalCount
            blockSize={18}
            blockMargin={5}
            showWeekdayLabels
            labels={{ weekdays: ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"] }}
            theme={{ dark }}
            renderBlock={(block, activity) => (
              <g className="text-slate-400">
                {block}
                <title>
                  {activity.count > 0
                    ? `${activity.count} task${activity.count > 1 ? "s" : ""} on ${activity.date}`
                    : `No tasks done on ${activity.date}`}
                </title>
              </g>
            )}
          />
        </CardContent>
      </Card>
    </motion.div>
  );
};

