            <Pencil size={14} aria-hidden="true" />
          </button>
          <button className="skald-note-row__delete" type="button" onClick={remove} disabled={!noteId} aria-label={`Delete ${note.title || 'note'}`}>
            <Trash2 size={14} aria-hidden="true" />
          </button>
        </div>
      )}
    </article>
  )
}

const NoteReminderWatcher = () => {
  const userId = useAppStore((state) => state.user?.id)
  const setActiveNoteId = useAppStore((state) => state.setActiveNoteId)
  const { data: notes = [] } = useNotes(userId)
  const navigate = useNavigate()
  const delivered = useRef(new Set<string>())

  useEffect(() => {
    if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return

    const checkReminders = () => {
      const now = Date.now()
      notes.forEach((note) => {
        if (!note._id || !note.reminderAt || note.archivedAt) return
        const dueAt = new Date(note.reminderAt).getTime()
        if (!Number.isFinite(dueAt) || dueAt > now) return

        const storageKey = `skald-note-reminder:${note._id}:${note.reminderAt}`
        if (delivered.current.has(storageKey)) return
        delivered.current.add(storageKey)

        try {
          const notification = new Notification(note.title || 'A note reminder', {
            body: 'A note you saved is due for a look.',
            tag: storageKey,
          })
          notification.onclick = () => {
            window.focus()
            setActiveNoteId(note._id ?? null)
            navigate('/app/notes')
            notification.close()
          }
        } catch (error) {
          delivered.current.delete(storageKey)
          console.error('Unable to show a note reminder notification:', error)
        }
      })
    }

    checkReminders()
    const intervalId = window.setInterval(checkReminders, 30_000)
    return () => window.clearInterval(intervalId)
  }, [navigate, notes, setActiveNoteId])

  return null
}

const Pagination = ({ page, pageCount, label, onPageChange }: PaginationProps) => {
  if (pageCount <= 1) return null

  const firstMiddlePage = Math.max(2, Math.min(page - 1, pageCount - 3))
  const visiblePages = pageCount <= 5
    ? Array.from({ length: pageCount }, (_, index) => index + 1)
    : [...new Set([
      1,
      pageCount,
      ...Array.from(
        { length: 3 },
        (_, index) => firstMiddlePage + index,
      ),
    ])].sort((first, second) => first - second)
  const pages = visiblePages.flatMap((pageNumber, index) => {
    const previousPage = visiblePages[index - 1]
    return previousPage && pageNumber - previousPage > 1
      ? [null, pageNumber]
      : [pageNumber]
  })

  return (
    <nav className="skald-pagination" aria-label={label}>
      <button
        type="button"
        className="skald-pagination__button"
        aria-label="Previous page"
        onClick={() => onPageChange(page - 1)}
        disabled={page <= 1}
      >
        <ChevronLeft size={15} aria-hidden="true" />
      </button>
      {pages.map((pageNumber, index) => pageNumber === null ? (
        <span key={`ellipsis-${index}`} className="skald-pagination__ellipsis" aria-hidden="true">…</span>
      ) : (
        <button
          key={pageNumber}
          type="button"
          className={`skald-pagination__button${pageNumber === page ? ' is-current' : ''}`}
          aria-label={`Page ${pageNumber}`}
          aria-current={pageNumber === page ? 'page' : undefined}
          onClick={() => onPageChange(pageNumber)}
        >
          {pageNumber}
        </button>
      ))}
      <button
        type="button"
        className="skald-pagination__button"
        aria-label="Next page"
        onClick={() => onPageChange(page + 1)}
        disabled={page >= pageCount}
      >
        <ChevronRight size={15} aria-hidden="true" />
      </button>
    </nav>
  )
}

