const WeeklyCalendar = ({ setCurrentDate }: { setCurrentDate: (value: string) => void}) => {
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [highlighted, setHighlighted] = useState<Date | null>(null)
  const isDark = useAppStore((state) => state.isDark)

  const today = new Date()

  const getWeekStartDate = (date: Date): Date => {
    const startDate = new Date(date);
    const dayOfWeek = startDate.getDay();
    startDate.setDate(startDate.getDate() - dayOfWeek);
    return startDate;
  };

  const generateWeekDays = (startDate: Date): Date[] => {
    const week: Date[] = [];
    for (let i = 0; i < 7; i++) {
      const day = new Date(startDate);
      day.setDate(startDate.getDate() + i);
      week.push(day);
    }
    return week;
  };

  const handleDateClick = (date: Date) => {
    setSelectedDate(date);
    setHighlighted(date)
    setCurrentDate(date.toLocaleDateString());
  };

  const weekStartDate = getWeekStartDate(selectedDate);
  const weekDays = generateWeekDays(weekStartDate);

  const headerDateString = selectedDate.toLocaleString("default", {
    month: "long",
    year: "numeric",
  });

  const dayNames: string[] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  return (
    <div className={`${isDark ? "text-gray-300 border-white/10 bg-white/2" : "text-[#2d3748] bg-white"} backdrop-blur-md border rounded-2xl h-[210px] shadow-md w-full p-[24px]`}>
      <div className="flex items-center justify-center mb-6">
        <h2 className="text-xl font-bold tracking-wider">{headerDateString}</h2>
      </div>

      <div className={`${isDark ? "bg-white/4" : "bg-white border"} p-4 rounded-xl shadow-sm`}>
        <div className="grid grid-cols-7 text-center">
          {dayNames.map((day) => (
            <div key={day} className={`text-sm font-medium mb-3 ${isDark ? "text-slate-400 mb-3" : "text-black/80"}`}>
              {day}
            </div>
          ))}

          {weekDays.map((day, index) => {
            const isSelected = day.toDateString() === highlighted?.toDateString();
            return (
              <div
                key={index}
                onClick={() => handleDateClick(day)}
                className="flex items-center justify-center cursor-pointer text-white mx-[2px]"
              >
                <div
                  className={`flex items-center justify-center h-10 w-10 rounded-lg text-md font-semibold transition-colors
                    ${isSelected ? (isDark ? "bg-[#5a69ff]" : "bg-[#602bf8]") : (isDark ? "bg-black/10 " : "bg-[#eae5f7] text-black/40")} shadow-xs ${today.toLocaleDateString() === day.toLocaleDateString() ? (isDark ? "border-2 border-white/80" : "border-2 border-black/60") : ""}`}
                >
                  {day.getDate()}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

const WorkspaceDialog = ({
  labelledBy,
  onClose,
  children,
  dark = false,
  className = '',
}: WorkspaceDialogProps) => {
  const dialogRef = useRef<HTMLDialogElement>(null)

  useEffect(() => {
    const dialog = dialogRef.current
    if (!dialog) return

    const previousFocus = document.activeElement
    dialog.showModal()
    dialog.querySelector<HTMLElement>('[autofocus]')?.focus()

    return () => {
      if (dialog.open) dialog.close()
      if (previousFocus instanceof HTMLElement) previousFocus.focus()
    }
  }, [])

  return (
    <dialog
      ref={dialogRef}
      className={`skald-task-dialog${dark ? ' skald-task-dialog--dark' : ''} ${className}`}
      aria-labelledby={labelledBy}
      onCancel={(event) => {
        event.preventDefault()
        onClose()
      }}
      onClick={(event) => {
        if (event.target === event.currentTarget) onClose()
      }}
    >
      {children}
    </dialog>
  )
}

