const AuthCallback = () => {
  const [error, setError] = useState<string | null>(null)
  const [sessionUserId, setSessionUserId] = useState<string | null>(null)
  const [finishingStartedAt, setFinishingStartedAt] = useState<number | null>(null)
  const [destinationReady, setDestinationReady] = useState(false)
  const location = useLocation()
  const navigate = useNavigate()
  const authLoading = useAppStore((state) => state.authLoading)
  const user = useAppStore((state) => state.user)
  const isDark = useAppStore((state) => state.isDark)
  const reducedMotion = useReducedMotion()
  const params = new URLSearchParams(location.search)
  const destination = getSafeAuthDestination(params.get('next'))
  const flow = params.get('flow') === 'signup' ? 'signup' : 'signin'

  useEffect(() => {
    let active = true
    const callbackParams = new URLSearchParams(location.search)
    const providerError = callbackParams.get('error_description') ?? callbackParams.get('error')

    if (providerError) {
      setError(providerError)
      return () => { active = false }
    }

    const finishAuthentication = async () => {
      const { data, error: sessionError } = await supabase.auth.getSession()
      if (sessionError) throw sessionError
      if (!data.session) throw new Error('This authentication link is invalid or has expired. Request a new link and try again.')
      if (!active) return

      const callbackDestination = getSafeAuthDestination(callbackParams.get('next'))
      if (callbackDestination === '/auth/update-password') {
        navigate(callbackDestination, { replace: true })
        return
      }

      setFinishingStartedAt(Date.now())
      setSessionUserId(data.session.user.id)
      await preloadDestination(callbackDestination)
      if (active) setDestinationReady(true)
    }

    void finishAuthentication().catch((reason: unknown) => {
      console.error('Unable to complete authentication callback:', reason)
      if (active) {
        setError(reason instanceof Error ? reason.message : 'Unable to complete sign-in. Please try again.')
      }
    })

    return () => { active = false }
  }, [location.search, navigate])

  useEffect(() => {
    if (sessionUserId === null || finishingStartedAt === null || !destinationReady || error || authLoading) return
    if (!user || user.id !== sessionUserId) {
      setError('Unable to load your workspace. Please sign in again.')
      return
    }

    const timeout = window.setTimeout(
      () => navigate(destination, { replace: true }),
      Math.max(0, finishingStartedAt + finishingPageDuration - Date.now()),
    )
    return () => window.clearTimeout(timeout)
  }, [authLoading, destination, destinationReady, error, finishingStartedAt, navigate, sessionUserId, user])

  return (
    <main className={`skald-auth-finish min-h-screen px-5 py-10 flex items-center justify-center ${
      isDark ? 'skald-auth-finish--dark' : 'skald-auth-finish--light'
    }`}>
      <motion.section
        className="skald-auth-finish__content w-full text-center"
        aria-live="polite"
        initial={reducedMotion ? false : { opacity: 0, scale: 0.99 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: reducedMotion ? 0 : 0.4, ease: 'easeOut' }}
      >
        <BrandMark className="skald-auth-finish__brand" />
        {!error && <span className="skald-auth-finish__spinner" aria-hidden="true" />}
        <h1 className="skald-auth-finish__title">
          {error
            ? `We couldn’t finish your ${flow === 'signup' ? 'sign-up' : 'sign-in'}`
            : `Finishing ${flow === 'signup' ? 'sign-up' : 'sign-in'}…`}
        </h1>
        {error && (
          <p role="alert" className={`skald-auth-finish__error ${isDark ? 'text-red-300' : 'text-red-700'}`}>
            {error}
          </p>
        )}
        {error && (
          <Link className="skald-auth-finish__link" to="/signin">Return to sign in</Link>
        )}
      </motion.section>
    </main>
  )
}

const Dashboard = () => {
  const user = useAppStore((state) => state.user)
  const userId = user?.id
  const setBreadcrumb = useAppStore((state) => state.setBreadcrumb)
  const { data: tasks = [], isLoading, error } = useTasks(userId)
  const { editTask } = useTaskMutations(userId)
  const now = new Date()
  const today = [
    now.getFullYear(),
    String(now.getMonth() + 1).padStart(2, '0'),
    String(now.getDate()).padStart(2, '0'),
  ].join('-')
  const todayTasks = tasks
    .filter((task) => task.date?.slice(0, 10) === today && task.status !== 'Cancelled')
    .sort((first, second) => (first.time ?? '').localeCompare(second.time ?? ''))
  const completedTodayTasks = todayTasks.filter((task) => task.completed).length
  const progressCircumference = 2 * Math.PI * 12
  const progressOffset = progressCircumference * (
    1 - (todayTasks.length ? completedTodayTasks / todayTasks.length : 0)
  )
  const firstName = user?.displayName.trim().split(/\s+/)[0] || 'there'
  const hour = now.getHours()
  const greeting = hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening'
  const dateLabel = new Intl.DateTimeFormat(undefined, {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
  }).format(now)

  useEffect(() => {
    setBreadcrumb('Today')
  }, [setBreadcrumb])

  const toggleTask = (task: (typeof todayTasks)[number]) => {
    if (!task._id) return
    const completed = !task.completed
    editTask.mutate({
      ...task,
      completed,
      completedAt: completed ? new Date() : null,
      status: completed ? 'Done' : 'Pending',
    })
  }

  if (isLoading) {
    return (
      <LoadingIndicator
        label="Loading today…"
        className="skald-today-page skald-loading-indicator--page"
      />
    )
  }

  return (
    <div className="skald-today-page">
      <header className="skald-today-heading">
        <div className="skald-today-heading__topline">
          <p>{dateLabel}</p>
          <Link to="/app/assistant">
            A little more clarity <Sparkles size={14} aria-hidden="true" />
          </Link>
        </div>
        <h1>{greeting}, {firstName}.</h1>
        <p className="skald-today-heading__subtitle">Here&apos;s a little room to begin.</p>
      </header>

      <Link to="/app/assistant" className="skald-today-nudge">
        <span className="skald-today-nudge__icon"><Sparkles size={19} aria-hidden="true" /></span>
        <span className="skald-today-nudge__copy">
          <span>A gentle nudge</span>
          <strong>Start with one thing. Let the rest wait.</strong>
        </span>
        <ArrowRight className="skald-today-nudge__arrow" size={18} aria-hidden="true" />
      </Link>

      {error ? (
        <p className="skald-today-error" role="alert">Unable to load today&apos;s tasks: {error.message}</p>
      ) : (
        <section className="skald-today-list" aria-labelledby="skald-today-list-title">
          <div className="skald-today-list__heading">
            <h2 id="skald-today-list-title">In your orbit</h2>
            <div className={`skald-today-list__progress-summary${
              todayTasks.length > 0 && completedTodayTasks === todayTasks.length ? ' is-complete' : ''
            }`}>
              {todayTasks.length > 0 && (
                <span
                  className="skald-today-progress"
                  role="progressbar"
                  aria-label="Today's task progress"
                  aria-valuemin={0}
                  aria-valuemax={todayTasks.length}
                  aria-valuenow={completedTodayTasks}
                  aria-valuetext={`${completedTodayTasks} of ${todayTasks.length} tasks complete`}
                >
                  <svg viewBox="0 0 28 28" aria-hidden="true">
                    <circle className="skald-today-progress__track" cx="14" cy="14" r="12" />
                    <circle
                      className="skald-today-progress__value"
                      cx="14"
                      cy="14"
                      r="12"
                      transform="rotate(-90 14 14)"
                      strokeDasharray={progressCircumference}
                      strokeDashoffset={progressOffset}
                    />
                  </svg>
                </span>
              )}
              <span>
                {todayTasks.length === 0
                  ? '0 things'
                  : completedTodayTasks === todayTasks.length
                    ? 'All clear'
                    : `${completedTodayTasks}/${todayTasks.length} done`}
              </span>
            </div>
          </div>

          {todayTasks.length > 0 ? (
            <ul>
              {todayTasks.map((task) => (
                <li key={task._id} className={task.completed ? 'is-completed' : ''}>
                  <button
                    type="button"
                    className="skald-today-task__check"
                    onClick={() => toggleTask(task)}
                    disabled={!task._id || editTask.isPending}
                    aria-label={`${task.completed ? 'Reopen' : 'Complete'} task: ${task.title ?? 'Untitled task'}`}
                    aria-pressed={Boolean(task.completed)}
                  >
                    {task.completed && <Check size={13} aria-hidden="true" />}
                  </button>
                  <span className="skald-today-task__title">{task.title || 'Untitled task'}</span>
                  {task.taskList && <span className="skald-today-task__list">{task.taskList}</span>}
                  {task.time && <time className="skald-today-task__time" dateTime={task.time}>{task.time}</time>}
                </li>
              ))}
            </ul>
          ) : (
            <div className="skald-today-list__empty">
              <p>Your day is open.</p>
              <Link to="/app/tasks?view=today&create=1">Add a task for today <ArrowRight size={14} /></Link>
            </div>
          )}
        </section>
      )}

      <Link to="/app/assistant" className="skald-today-assistant">
        <Sparkles size={16} aria-hidden="true" />
        <span>Need a hand finding the next step?</span>
        <ArrowRight size={17} aria-hidden="true" />
      </Link>
    </div>
  )
}

const SplitTextWord = ({ word, reducedMotion }: { word: string; reducedMotion: boolean | null }) => (
  <motion.span
    className="skald-hero__word"
    variants={{
      hidden: {},
      visible: { transition: { staggerChildren: reducedMotion ? 0 : 0.025 } },
    }}
  >
    {Array.from(word).map((letter, index) => (
      <motion.span
        className="skald-hero__letter"
        key={`${letter}-${index}`}
        variants={{
          hidden: { opacity: 0, scale: 0.78 },
          visible: {
            opacity: 1,
            scale: 1,
            transition: { duration: reducedMotion ? 0 : 0.36, ease: "easeOut" },
          },
        }}
      >
        {letter}
      </motion.span>
    ))}
  </motion.span>
)

const UpdatePassword = () => {
  const [checkingSession, setCheckingSession] = useState(true)
  const [hasSession, setHasSession] = useState(false)
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [complete, setComplete] = useState(false)
  const navigate = useNavigate()
  const reducedMotion = useReducedMotion()

  useEffect(() => {
    let active = true
    void supabase.auth.getSession().then(({ data, error: sessionError }) => {
      if (!active) return
      if (sessionError) {
        setError(sessionError.message)
      } else {
        setHasSession(Boolean(data.session))
      }
      setCheckingSession(false)
    }).catch((reason: unknown) => {
      console.error('Unable to verify password recovery session:', reason)
      if (active) {
        setError(reason instanceof Error ? reason.message : 'Unable to verify your reset link.')
        setCheckingSession(false)
      }
    })
    return () => { active = false }
  }, [])

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    setError(null)
    if (password.length < 12) {
      setError('Use a password with at least 12 characters.')
      return
    }
    if (password !== confirmPassword) {
      setError('Your passwords do not match.')
      return
    }

    setLoading(true)
    try {
      const { error: updateError } = await supabase.auth.updateUser({ password })
      if (updateError) throw updateError
      setComplete(true)
      setPassword('')
      setConfirmPassword('')
      window.setTimeout(() => navigate('/app/today', { replace: true }), 1200)
    } catch (reason) {
      console.error('Unable to update password:', reason)
      setError(reason instanceof Error ? reason.message : 'Unable to update your password. Request a new reset link and try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <main className="min-h-screen bg-[#0f111a] px-5 py-10 text-white flex items-center justify-center">
      <motion.section
        className="w-full max-w-md rounded-3xl border border-white/15 bg-white/[0.04] p-7 shadow-2xl shadow-black/30 sm:p-9"
        initial={reducedMotion ? false : { opacity: 0, scale: 0.99 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: reducedMotion ? 0 : 0.4, ease: 'easeOut' }}
      >
        <BrandMark className="mx-auto mb-4 size-11" />
        <h1 className="text-center text-2xl font-semibold">Choose a new password</h1>
        {checkingSession ? (
          <p className="mt-5 text-center text-sm text-white/65">Verifying your secure reset link…</p>
        ) : !hasSession ? (
          <div className="mt-5 text-center">
            <p role="alert" className="text-sm text-red-300">
              {error ?? 'This reset link is invalid or has expired. Request a new one to continue.'}
            </p>
            <Link className="mt-5 inline-block text-indigo-200 underline underline-offset-4" to="/signin">Request another link</Link>
          </div>
        ) : complete ? (
          <p role="status" aria-live="polite" className="mt-5 text-center text-sm text-emerald-200">
            Password updated. Taking you to your workspace…
          </p>
        ) : (
          <form className="mt-6 space-y-4" onSubmit={handleSubmit}>
            <label className="block text-sm text-white/75">
              New password
              <input
                autoComplete="new-password"
                className="mt-1.5 min-h-11 w-full rounded-xl border border-white/15 bg-black/20 px-3 text-white outline-none focus:border-indigo-300"
                minLength={12}
                onChange={(event) => setPassword(event.target.value)}
                required
                type="password"
                value={password}
              />
              <span className="mt-1 block text-xs text-white/50">Use at least 12 characters.</span>
            </label>
            <label className="block text-sm text-white/75">
              Confirm new password
              <input
                autoComplete="new-password"
                className="mt-1.5 min-h-11 w-full rounded-xl border border-white/15 bg-black/20 px-3 text-white outline-none focus:border-indigo-300"
                minLength={12}
                onChange={(event) => setConfirmPassword(event.target.value)}
                required
                type="password"
                value={confirmPassword}
              />
            </label>
            {error && <p role="alert" className="text-sm text-red-300">{error}</p>}
            <button
              className="min-h-12 w-full rounded-xl bg-indigo-500 px-4 font-semibold transition hover:bg-indigo-400 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-200 disabled:cursor-wait disabled:opacity-60"
              disabled={loading}
              type="submit"
            >
              {loading ? 'Updating…' : 'Update password'}
            </button>
          </form>
        )}
      </motion.section>
    </main>
  )
}
